const items = $input.all();
const rawNormalized = [];

for (const item of items) {
  const data = item.json;
  let rawUrl = data.link || data.url || data.guid || '';
  if (!rawUrl || typeof rawUrl !== 'string') continue;

  let cleanUrl = rawUrl;
  try {
    const urlObj = new URL(rawUrl);
    const searchParams = new URLSearchParams();
    for (const [key, val] of urlObj.searchParams.entries()) {
      if (!key.startsWith('utm_') && !['ref', 'source', 'fbclid', 'gclid'].includes(key)) {
        searchParams.append(key, val);
      }
    }
    urlObj.search = searchParams.toString() ? '?' + searchParams.toString() : '';
    urlObj.hash = '';
    cleanUrl = urlObj.toString();
  } catch (e) {
    cleanUrl = rawUrl.split('?')[0].split('#')[0];
  }

  // Extract the fullest substantive content available from the feed
  let rawSnippet = data['content:encoded'] || data.content || data.summary || data.description || data.contentSnippet || '';
  let cleanDesc = String(rawSnippet)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '\"')
    .replace(/\\s+/g, ' ')
    .trim()
    .slice(0, 3000);

  let sourceName = 'Tech Announcement';
  if (cleanUrl.includes('techcrunch.com')) sourceName = 'TechCrunch AI';
  else if (cleanUrl.includes('huggingface.co')) sourceName = 'Hugging Face';
  else if (cleanUrl.includes('github.blog')) sourceName = 'GitHub Blog';
  else if (cleanUrl.includes('simonwillison.net')) sourceName = 'Simon Willison';
  else if (cleanUrl.includes('ycombinator.com') || cleanUrl.includes('hnrss.org')) sourceName = 'Hacker News';

  rawNormalized.push({
    title: (data.title || '').trim(),
    url: cleanUrl,
    sourceName: sourceName,
    pubDate: data.pubDate || data.isoDate || new Date().toISOString(),
    description: cleanDesc
  });
}

// Keep only the most recent 15 items per source to avoid processing legacy archive feeds
const sourceCounts = {};
const filtered = [];

for (const entry of rawNormalized) {
  sourceCounts[entry.sourceName] = (sourceCounts[entry.sourceName] || 0) + 1;
  if (sourceCounts[entry.sourceName] <= 15) {
    filtered.push({ json: entry });
  }
}

return filtered;

const items = $input.all();
const scored = [];

const highValueKeywords = [
  'ai', 'llm', 'gpt', 'gemini', 'claude', 'agent', 'automation', 'n8n',
  'workflow', 'github', 'open source', 'open-source', 'repository', 'tool',
  'python', 'javascript', 'framework', 'demo', 'breakthrough', 'model',
  'productivity', 'terminal', 'coding', 'developer', 'prompt', 'api'
];

const lowValueKeywords = [
  'lawsuit', 'sued', 'earnings', 'quarterly', 'shares fall', 'stocks',
  'investors', 'layoffs', 'merger', 'acquisition', 'regulatory', 'eu fine'
];

for (const item of items) {
  const data = item.json;
  const text = `${data.title} ${data.description}`.toLowerCase();

  let score = 0;
  for (const kw of highValueKeywords) {
    if (text.includes(kw)) score += 2;
  }
  for (const kw of lowValueKeywords) {
    if (text.includes(kw)) score -= 4;
  }

  if (text.includes('github.com') || text.includes('release') || text.includes('tutorial')) score += 3;
  if (text.includes('workflow') || text.includes('n8n') || text.includes('agent')) score += 4;

  if (score >= 4) {
    scored.push({ item: data, score });
  }
}

scored.sort((a, b) => b.score - a.score);
// Pick top 2 highest scoring discoveries
const topArticles = (scored.length > 0 ? scored.slice(0, 2) : items.slice(0, 2)).map(s => s.item || s.json);

const articlesSummary = topArticles.map((a, idx) => `ARTICLE ${idx + 1}:
- Title: ${a.title}
- Source: ${a.sourceName}
- URL: ${a.url}
- Article Content: ${a.description}
`).join('\n---\n');

const prompt = `You are an elite AI tech research specialist and short-form video producer. Your mission is to provide an in-depth, verified factual briefing on these tech discoveries so a creator can understand everything without reading the original article.

Analyze these 2 curated tech discoveries:
${articlesSummary}

For EACH discovery, provide a comprehensive briefing and ready-to-shoot Instagram Reel concept.
Return a STRICT JSON ARRAY of 2 objects (one for each article) matching this exact schema:
[
  {
    "article_index": 1,
    "topic_title": "Punchy topic title under 50 characters",
    "category": "AI Tools & Automation",
    "relevance_score": 9,
    "in_depth_summary": "Comprehensive 3-5 sentence factual explanation explaining exactly what the tool/feature is, the underlying technical mechanics (how it works, architecture, models), and why it is a major development for builders.",
    "target_audience": "Who this is for (e.g. full-stack developers, AI automators) and why it stops their scroll.",
    "verified_specs_and_facts": [
      "Pricing / License: Exact cost model (e.g. Free tier, token pricing, or open-source license)",
      "System Requirements: Required runtime or prerequisites (e.g. Docker, Python, Cloud API, or local GPU)",
      "Key Technical Benchmark / Standout Spec: Specific metric or technical capability from the source"
    ],
    "hook": "Exact high-retention 3-second opening hook line to speak on camera, plus [ON-SCREEN TEXT] directions.",
    "reel_concept": "Complete 20-45 second video flow:\n• [0-5s] Hook (high-energy intro)\n• [5-15s] Context (why existing approaches fall short)\n• [15-35s] Visual Demo (exact screen steps: CLI run, repo demo, or UI interaction)\n• [35-45s] Takeaway & CTA (concrete next step).",
    "talking_points": [
      "Detailed Point 1 with exact technical facts and capabilities from the source",
      "Detailed Point 2 explaining why this is better or different from alternatives",
      "Detailed Point 3 explaining the concrete next step to try or implement it"
    ],
    "recording_format": "Screen Recording + Face Cam Bubble",
    "visual_demo_guide": "Precise visual direction: what browser tab, terminal command, GitHub repo, or UI to show on screen.",
    "claims_and_verification": "Verified facts vs caveats: what is confirmed in the source vs prerequisites to check before recording."
  }
]

CRITICAL RULES:
- Never fabricate benchmarks, stars, or statistics.
- Extract concrete facts, names, and details directly from the provided article content.
- Return ONLY the valid raw JSON array. No conversational text.`;

return [{
  json: {
    articles: topArticles,
    ai_prompt: prompt
  }
}];

const items = $input.all();
const preFilterNode = $('Pre-Filter & Rank Candidates').first();
const sourceArticles = preFilterNode?.json?.articles || [];

let rawText = '';
const item = items[0] || {};
if (typeof item.json?.text === 'string') {
  rawText = item.json.text;
} else if (item.json?.content?.parts?.[0]?.text) {
  rawText = item.json.content.parts[0].text;
} else if (typeof item.json?.content === 'string') {
  rawText = item.json.content;
} else if (item.json?.response?.text) {
  rawText = item.json.response.text;
} else if (typeof item.json?.output === 'string') {
  rawText = item.json.output;
}

let generatedList = [];
if (rawText) {
  try {
    let cleanJson = String(rawText).trim();
    if (cleanJson.startsWith('```')) {
      cleanJson = cleanJson.replace(/^```[a-z]*\n?/i, '').replace(/\n?```$/, '').trim();
    }
    const parsed = JSON.parse(cleanJson);
    if (Array.isArray(parsed)) {
      generatedList = parsed;
    } else if (typeof parsed === 'object' && parsed !== null) {
      generatedList = [parsed];
    }
  } catch (err) {
    console.error('Failed to parse AI output JSON array:', err.message);
  }
}

const formatted = [];
const count = Math.max(sourceArticles.length, generatedList.length, 1);

for (let i = 0; i < count; i++) {
  const source = sourceArticles[i] || {};
  let ai = generatedList[i];

  if (!ai || typeof ai !== 'object') {
    ai = {
      topic_title: source.title || 'Trending Tech Discovery',
      category: 'AI Tools & Automation',
      relevance_score: 8,
      in_depth_summary: source.description || 'Curated discovery from tech scout.',
      target_audience: 'Developers and automation builders interested in new AI tools.',
      verified_specs_and_facts: [
        `Source Publisher: ${source.sourceName || 'Web Announcement'}`,
        'Check original article for exact pricing and licensing details',
        `Published Date: ${source.pubDate ? new Date(source.pubDate).toISOString().split('T')[0] : 'Recent'}`
      ],
      hook: `Did you see what just dropped in tech? [ON-SCREEN TEXT: Check this out 🚀]`,
      reel_concept: `• [0-5s] Hook: Announce the discovery\n• [5-15s] Show context and why it matters\n• [15-35s] Walk through the project link or repo\n• [35-45s] Key takeaway & CTA`,
      talking_points: [
        `Core capability announced by ${source.sourceName || 'the developer'}`,
        'Why this is worth testing in your workflow',
        `Check link in description: ${source.url || ''}`
      ],
      recording_format: 'Screen Recording + Face Cam',
      visual_demo_guide: 'Screen capture of original post or GitHub repository',
      claims_and_verification: 'Verify free tier availability and compatibility'
    };
  }

  const score = Number(ai.relevance_score) || 8;
  const talkingPointsList = Array.isArray(ai.talking_points)
    ? ai.talking_points.map((pt, idx) => `${idx + 1}. ${pt}`).join('\n\n')
    : String(ai.talking_points || '');

  const specsList = Array.isArray(ai.verified_specs_and_facts)
    ? ai.verified_specs_and_facts.map(s => `• ${s}`).join('\n')
    : String(ai.verified_specs_and_facts || '');

  const section1 = `📌 EXECUTIVE TOPIC SUMMARY:
${ai.in_depth_summary || ai.summary || source.description || 'N/A'}

🎯 TARGET AUDIENCE:
${ai.target_audience || 'AI Developers & Automation Builders'}`.slice(0, 1900);

  const section2 = `🔍 VERIFIED SPECS & FACT-CHECK:
${specsList}`.slice(0, 1900);

  const section3 = `🎬 INSTAGRAM REEL SCRIPT (20–45s):
🎣 3-Second Opening Hook:
"${ai.hook || 'N/A'}"

⏱️ Step-By-Step Video Breakdown:
${ai.reel_concept || 'N/A'}`.slice(0, 1900);

  const section4 = `💡 KEY TALKING POINTS:
${talkingPointsList}`.slice(0, 1900);

  const section5 = `💻 VISUAL DEMO GUIDE:
${ai.visual_demo_guide || ai.visual_demo || 'N/A'}

⚠️ VERIFICATION & CAVEATS:
${ai.claims_and_verification || ai.claims_to_verify || 'Check source URL before recording.'}

🔗 SOURCE & REFERENCES:
Source: ${source.sourceName || 'Web'}
URL: ${source.url || 'N/A'}`.slice(0, 1900);

  formatted.push({
    json: {
      title: (ai.topic_title || source.title || 'Untitled Idea').slice(0, 100),
      category: ai.category || 'AI Tools & Automation',
      url: source.url || '',
      sourceName: source.sourceName || 'Web',
      pubDate: source.pubDate ? new Date(source.pubDate).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
      summary: ai.in_depth_summary || ai.summary || '',
      relevance_score: score,
      status: 'Inbox',
      dateDiscovered: new Date().toISOString().split('T')[0],
      section_summary: section1,
      section_specs: section2,
      section_script: section3,
      section_talking_points: section4,
      section_verification: section5
    }
  });
}

return formatted;
